toolCalls.args:
{"command":"$ErrorActionPreference='SilentlyContinue'
$lines = Get-Content .\input\session.jsonl
$out = foreach($l in $lines){
  if($l -notmatch '"type":"response_item"'){continue}
  $o = $null
  try { $o = $l | ConvertFrom-Json } catch { }
  if(-not $o){continue}
  $p = $o.payload
  if($p.type -eq 'message'){
    if($p.role -eq 'assistant'){
      $txt = ($p.content | Where-Object { $_.type -eq 'output_text' } | ForEach-Object { $_.text }) -join ' '
      if($txt){ [pscustomobject]@{ord=$o.ordinal; role='A'; phase=$p.phase; len=$txt.Length; text=$txt.Substring(0,[Math]::Min(400,$txt.Length))} }
    } elseif($p.role -eq 'user'){
      $txt = ($p.content | Where-Object { $_.type -eq 'input_text' } | ForEach-Object { $_.text }) -join ' '
      if($txt -and $txt -notmatch '^<' -and $txt -notmatch 'recommended_plugins'){ [pscustomobject]@{ord=$o.ordinal; role='U'; phase=''; len=$txt.Length; text=$txt.Substring(0,[Math]::Min(2000,$txt.Length))} }
    }
  } elseif($p.type -eq 'custom_tool_call'){
    [pscustomobject]@{ord=$o.ordinal; role='TOOL'; phase=$p.name; len=0; text=(($p.input -replace '\s+',' ').Substring(0,[Math]::Min(300,($p.input -replace '\s+',' ').Length)))}
  } elseif($p.type -eq 'reasoning'){ }
}
$out | Sort-Object ord | Format-Table -Wrap -AutoSize | Out-String -Width 300"}

{"command":"$ErrorActionPreference='SilentlyContinue'
$lines = Get-Content .\input\session.jsonl
"line_count=$($lines.Count)"
$maxOrd=-1; foreach($l in $lines){ if($l -match '"ordinal":(\d+)'){ $v=[int]$Matches[1]; if($v -gt $maxOrd){$maxOrd=$v} } }
"max_ordinal=$maxOrd"
$out = foreach($l in $lines){
  $o = $null
  try { $o = $l | ConvertFrom-Json } catch { }
  if(-not $o){continue}
  $p = $o.payload
  $kind = $o.type
  if($kind -eq 'response_item'){
    if($p.type -eq 'message'){
      if($p.role -eq 'assistant'){
        $txt = ($p.content | Where-Object { $_.type -eq 'output_text' } | ForEach-Object { $_.text }) -join ' '
        if($txt){ [pscustomobject]@{ord=$o.ordinal; kind="A/$($p.phase)"; len=$txt.Length; text=$txt.Substring(0,[Math]::Min(500,$txt.Length))} }
      } elseif($p.role -eq 'user'){
        $txt = ($p.content | Where-Object { $_.type -eq 'input_text' } | ForEach-Object { $_.text }) -join ' '
        if($txt -and $txt -notmatch '^<' -and $txt -notmatch 'recommended_plugins'){ [pscustomobject]@{ord=$o.ordinal; kind='USER'; len=$txt.Length; text=$txt.Substring(0,[Math]::Min(900,$txt.Length))} }
      }
    } elseif($p.type -eq 'custom_tool_call'){
      $name = $p.name; $status=$p.status; [pscustomobject]@{ord=$o.ordinal; kind="TOOL:$name:$status"; len=0; text=''}
    } elseif($p.type -eq 'function_call'){
      [pscustomobject]@{ord=$o.ordinal; kind="FC:$($p.name)"; len=0; text=''}
    }
  } elseif($kind -eq 'event_msg'){
    [pscustomobject]@{ord=$o.ordinal; kind="EV:$($p.type)"; len=0; text=($p.message)} 
  }
}
$out | Where-Object { $_.ord -ge 459 } | Sort-Object ord | Format-Table -Wrap -AutoSize | Out-String -Width 280"}

{"command":"$ErrorActionPreference='SilentlyContinue'
$lines = Get-Content .\input\session.jsonl
$maxOrd=-1; foreach($l in $lines){ if($l -match '"ordinal":(\d+)'){ $v=[int]$Matches[1]; if($v -gt $maxOrd){$maxOrd=$v} } }
"max_ordinal=$maxOrd"
$out = foreach($l in $lines){
  $o = $null
  try { $o = $l | ConvertFrom-Json } catch { }
  if(-not $o){continue}
  $p = $o.payload
  if($o.type -eq 'response_item'){
    if($p.type -eq 'message'){
      if($p.role -eq 'assistant'){
        $txt = ($p.content | Where-Object { $_.type -eq 'output_text' } | ForEach-Object { $_.text }) -join ' '
        if($txt){ [pscustomobject]@{ord=$o.ordinal; kind=('A/' + $p.phase); len=$txt.Length; text=$txt.Substring(0,[Math]::Min(500,$txt.Length))} }
      } elseif($p.role -eq 'user'){
        $txt = ($p.content | Where-Object { $_.type -eq 'input_text' } | ForEach-Object { $_.text }) -join ' '
        if($txt -and $txt -notmatch '^<' -and $txt -notmatch 'recommended_plugins'){ [pscustomobject]@{ord=$o.ordinal; kind='USER'; len=$txt.Length; text=$txt.Substring(0,[Math]::Min(1200,$txt.Length))} }
      }
    } elseif($p.type -eq 'custom_tool_call'){
      [pscustomobject]@{ord=$o.ordinal; kind=('TOOL:' + $p.name + ':' + $p.status); len=0; text=''}
    } elseif($p.type -eq 'function_call'){
      [pscustomobject]@{ord=$o.ordinal; kind=('FC:' + $p.name); len=0; text=''}
    }
  } elseif($o.type -eq 'event_msg'){
    [pscustomobject]@{ord=$o.ordinal; kind=('EV:' + $p.type); len=0; text=[string]$p.message}
  }
}
$out | Where-Object { $_.ord -ge 459 } | Sort-Object ord | Format-Table -Wrap -AutoSize | Out-String -Width 280"}

{"command":"$ErrorActionPreference='SilentlyContinue'
$lines = Get-Content .\input\session.jsonl
foreach($l in $lines){
  if($l -notmatch '"type":"event_msg"'){continue}
  $o = $null; try { $o = $l | ConvertFrom-Json } catch { }
  if(-not $o){continue}
  $p = $o.payload
  if($p.type -eq 'item_completed'){
    $it = $p.item
    if($it.type -eq 'CommandExecution'){
      "ord=$($o.ordinal) item=CommandExecution status=$($it.status) exit=$($it.exit_code) cmd=$($it.command -join ' ')"
    }
  }
}"}

{"command":"$lines = Get-Content .\input\session.jsonl
"total=$($lines.Count)"
$idx=0
foreach($l in $lines){
  if($l -match '"ordinal":(46[0-9]|47[0-3])'){
    $snip = $l
    if($snip.Length -gt 2600){ $snip = $snip.Substring(0,2600) + ' ...<TRUNC> len=' + $l.Length }
    "[$idx] $snip`n"
  }
  $idx++
} | Out-String -Width 300"}

{"command":"$lines = Get-Content .\input\session.jsonl
"total=$($lines.Count)"
$res = foreach($l in $lines){
  if($l -match '"ordinal":(46\d|47[0-3])'){
    $snip = $l
    if($snip.Length -gt 3000){ $snip = $snip.Substring(0,3000) + ' ...<TRUNC total=' + $l.Length + '>' }
    "[$($Matches[1])] $snip`n"
  }
}
$res -join "`n" | Out-String -Width 320"}

{"command":"$lines = Get-Content .\input\session.jsonl
$res = foreach($l in $lines){
  if($l -match '"role":"user"'){
    if($l -match '"ordinal":(\d+)'){ $ord=[int]$Matches[1] } else { $ord=-1 }
    $txt=''
    $o=$null; try { $o=$l|ConvertFrom-Json } catch {}
    if($o){ $c=$o.payload.content; if($c){ $txt=(($c|Where-Object{$_.type -eq 'input_text'}|ForEach-Object{$_.text}) -join ' ') } }
    if($txt.Length -gt 160){ $txt=$txt.Substring(0,160) }
    "ord=$ord len=$($txt.Length) text=$txt"
  }
}
$res -join "`n""}

{"command":""--- HEAD ---"; Get-Content .\workspace\.git\HEAD
"--- branches ---"; Get-ChildItem .\workspace\.git\refs\heads -Recurse -File -ErrorAction SilentlyContinue | ForEach-Object { $_.FullName.Substring($_.FullName.IndexOf('refs\heads')) + ' -> ' + (Get-Content $_.FullName -Raw).Trim() }
"--- packed-refs (head) ---"; Get-Content .\workspace\.git\packed-refs -ErrorAction SilentlyContinue | Select-Object -First 60
"--- refs/codex ---"; Get-ChildItem .\workspace\.git\refs\codex -Recurse -File -ErrorAction SilentlyContinue | Select-Object -First 20 | ForEach-Object { $_.FullName.Substring($_.FullName.IndexOf('refs\codex')) }"}
